# Generated by build.py from recipe.yml for recipe ftp-resume-an-interrupted-download. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'mkdir site'
cmd /c 'head -c 200000 /dev/urandom > site/update.iso'
cmd /c 'head -c 65536 site/update.iso > update.iso'
cmd /c 'head -c 65536 site/update.iso > second.iso'
cmd /c 'head -c 65536 site/update.iso > third.iso'
cmd /c 'head -c 65536 site/update.iso > fourth.iso'
cmd /c 'head -c 65536 /dev/zero > bad.iso'
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--directory', 'site', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -C - -o update.iso -w "%{size_download}\n" ftp://127.0.0.1:8080/update.iso } finally { Stop-Process $server0 }
